+
+    fn namespace(name: &str, functions: &[&str]) -> serde_json::Value {
+        json!({
+            "type": "namespace",
+            "name": name,
+            "description": "Grouped tools.",
+            "tools": functions
+                .iter()
+                .map(|function| json!({"type": "function", "name": function}))
